  const grip=fitPalmPrimitive(left,normal,axis,G.gripRadius,G.gripHeight,mapped(armSurfaces.left)),nock=fitPalmPrimitive(right,normal,axis,G.nockRadius,null,mapped(armSurfaces.right));
